import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Car, 
  Store, 
  Mail, 
  Lock, 
  Phone, 
  ArrowRight,
  Loader2,
  CheckCircle2,
  Globe,
  AlertCircle
} from 'lucide-react';
import api from '../../lib/api';
import toast, { Toaster } from 'react-hot-toast';
import { ROUTES } from '../../constants/routes';
import { API_ENDPOINTS } from '../../constants/endpoints';

interface FieldErrors {
    businessName?: string;
    fullName?: string;
    email?: string;
    phone?: string;
    password?: string;
    [key: string]: string | undefined;
}

const Register = () => {
    const navigate = useNavigate();
    const [loading, setLoading] = useState(false);
    const [step, setStep] = useState(1);
    const [formData, setFormData] = useState({
        businessName: '',
        fullName: '',
        email: '',
        phone: '',
        password: '',
    });
    const [error, setError] = useState('');
    const [fieldErrors, setFieldErrors] = useState<FieldErrors>({});

    const validateStep1 = () => {
        const errors: FieldErrors = {};
        if (!formData.businessName || formData.businessName.length < 2) {
            errors.businessName = 'Business name must be at least 2 characters';
        }
        setFieldErrors(errors);
        return Object.keys(errors).length === 0;
    };

    const validateStep2 = () => {
        const errors: FieldErrors = {};
        if (!formData.fullName || formData.fullName.length < 2) {
            errors.fullName = 'Full name is required';
        }
        if (!formData.email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
            errors.email = 'Please enter a valid email address';
        }
        if (!formData.phone || !/^\+?[0-9]{10,15}$/.test(formData.phone.replace(/\s/g, ''))) {
            errors.phone = 'Please enter a valid phone number (min 10 digits)';
        }
        if (!formData.password || formData.password.length < 8) {
            errors.password = 'Password must be at least 8 characters';
        }
        setFieldErrors(errors);
        return Object.keys(errors).length === 0;
    };

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, value } = e.target;
        setFormData({ ...formData, [name]: value });
        if (error) setError('');
        if (fieldErrors[name]) {
            setFieldErrors({ ...fieldErrors, [name]: '' });
        }
    };

    const handleNext = (e: React.FormEvent) => {
        e.preventDefault();
        if (validateStep1()) {
            setStep(2);
        } else {
            toast.error("Please fix the errors before continuing");
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!validateStep2()) {
            toast.error("Please fix the errors before submitting");
            return;
        }

        setLoading(true);
        setError('');

        const payload = {
            tenantData: {
                name: formData.businessName,
                expiryDate: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000) // Default 30 days
            },
            adminData: {
                fullName: formData.fullName,
                email: formData.email,
                phone: formData.phone,
                password: formData.password
            }
        };

        try {
            await api.post(API_ENDPOINTS.AUTH.REGISTER_TENANT, payload);
            toast.success("Dealership registered! Redirecting to login...");
            setTimeout(() => navigate(ROUTES.LOGIN), 2000);
        } catch (err: any) {
            const message = err.response?.data?.message || err.message || 'Registration failed. Check your data.';
            setError(message);
            toast.error(message);
            setFormData(prev => ({ ...prev, password: '' }));
        } finally {
            setLoading(false);
        }
