import React, { useState, useEffect } from 'react';
import { Layout, Plus, Trash2, GripVertical, Settings2, Loader2, Save } from 'lucide-react';
import api from '../../lib/api';
import toast from 'react-hot-toast';

const FormBuilder = () => {
    const [tenants, setTenants] = useState([]);
    const [selectedTenant, setSelectedTenant] = useState(null);
    const [fields, setFields] = useState([]);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);

    useEffect(() => {
        const fetchTenants = async () => {
            try {
                const { data } = await api.get('/super/tenants');
                setTenants(data.data);
                if (data.data.length > 0) {
                    setSelectedTenant(data.data[0]);
                }
            } catch (error) {
                toast.error("Failed to fetch showrooms");
            } finally {
                setLoading(false);
            }
        };
        fetchTenants();
    }, []);

    useEffect(() => {
        if (selectedTenant) {
            fetchFields(selectedTenant._id);
        }
    }, [selectedTenant]);

    const fetchFields = async (tenantId) => {
        try {
            const { data } = await api.get(`/super/tenants/${tenantId}/form-fields`);
            setFields(data.data || []);
        } catch (error) {
            console.error("Failed to fetch fields", error);
            setFields([]);
        }
    };

    const addField = () => {
        const newField = {
            id: Date.now(),
            name: `field_${fields.length + 1}`,
            label: 'New Field',
            type: 'text',
            required: false,
            placeholder: 'Enter something...'
        };
        setFields([...fields, newField]);
    };

    const removeField = (id) => {
        setFields(fields.filter(f => f.id !== id));
    };

    const handleSave = async () => {
        if (!selectedTenant) return;
        setSaving(true);
        try {
            await api.post(`/super/tenants/${selectedTenant._id}/form-fields`, { fields });
            toast.success("Form structure saved!");
        } catch (error) {
            toast.error("Failed to save form structure");
        } finally {
            setSaving(false);
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-64">
                <Loader2 className="w-8 h-8 animate-spin text-indigo-600" />
            </div>
        );
    }

    return (
        <div className="space-y-8">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-black text-slate-900 tracking-tight">Dynamic Form Builder</h1>
                    <p className="text-slate-500 font-medium mt-1">Configure lead generation fields for your partners.</p>
                </div>
                <button 
                    onClick={handleSave}
                    disabled={saving}
                    className="bg-slate-900 text-white px-8 py-3 rounded-2xl font-bold flex items-center gap-3 hover:bg-slate-800 transition-all shadow-xl shadow-slate-200 disabled:opacity-50"
                >
                    {saving ? <Loader2 size={18} className="animate-spin" /> : <Save size={18} />}
                    Save Structure
                </button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
                {/* Sidebar: Tenant Selection */}
                <div className="lg:col-span-1 space-y-4">
                    <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest px-2">Showrooms</h3>
                    <div className="space-y-2">
                        {tenants.map((t) => (
                            <button
                                key={t._id}
                                onClick={() => setSelectedTenant(t)}
                                className={`w-full text-left px-5 py-4 rounded-2xl font-bold text-sm transition-all border ${selectedTenant?._id === t._id ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg shadow-indigo-100' : 'bg-white border-slate-100 text-slate-600 hover:border-indigo-200'}`}
                            >
                                {t.name}
                            </button>
                        ))}
                    </div>
                </div>

                {/* Main: Builder UI */}
                <div className="lg:col-span-3 bg-white rounded-[2rem] border border-slate-100 shadow-xl shadow-slate-200/50 p-8 min-h-[500px]">
                    <div className="flex items-center justify-between mb-8">
                        <div className="flex items-center gap-3">
                            <div className="p-3 bg-slate-50 rounded-xl">
                                <Layout className="text-slate-600" size={20} />
                            </div>
                            <div>
                                <h3 className="text-lg font-bold text-slate-900">{selectedTenant?.name} Form</h3>
                                <p className="text-xs font-medium text-slate-400">Total Fields: {fields.length}</p>
                            </div>
                        </div>
                        <button 
                            onClick={addField}
                            className="text-indigo-600 bg-indigo-50 px-4 py-2 rounded-xl font-bold text-xs hover:bg-indigo-100 transition-all flex items-center gap-2"
                        >
                            <Plus size={16} />
                            Add Field
                        </button>
                    </div>

                    <div className="space-y-4">
                        {fields.length === 0 ? (
                            <div className="py-20 text-center border-2 border-dashed border-slate-100 rounded-3xl">
                                <p className="text-slate-400 font-medium">No fields defined yet. Click "Add Field" to start.</p>
                            </div>
                        ) : fields.map((field, index) => (
                            <div key={field.id || index} className="group p-6 bg-slate-50/50 border border-slate-100 rounded-3xl flex items-center gap-6 hover:bg-white hover:border-indigo-200 transition-all duration-300">
                                <GripVertical className="text-slate-300 cursor-move" size={20} />

                                <div className="grid grid-cols-1 md:grid-cols-3 gap-4 flex-1">
                                    <input 
                                        type="text" 
                                        placeholder="Label (e.g. Phone Number)"
                                        value={field.label}
                                        onChange={(e) => {
                                            const newFields = [...fields];
                                            newFields[index].label = e.target.value;
                                            setFields(newFields);
                                        }}
                                        className="bg-white border border-slate-100 px-4 py-2 rounded-xl text-sm font-bold focus:outline-none focus:ring-2 focus:ring-indigo-500/20"
                                    />
                                    <select 
                                        value={field.type}
                                        onChange={(e) => {
                                            const newFields = [...fields];
                                            newFields[index].type = e.target.value;
                                            setFields(newFields);
                                        }}
                                        className="bg-white border border-slate-100 px-4 py-2 rounded-xl text-sm font-bold focus:outline-none focus:ring-2 focus:ring-indigo-500/20"
                                    >
                                        <option value="text">Short Text</option>
                                        <option value="textarea">Long Text</option>
                                        <option value="number">Number</option>
                                        <option value="email">Email</option>
                                    </select>
                                    <div className="flex items-center gap-2">
                                        <label className="text-xs font-black text-slate-400 uppercase tracking-tighter">Required</label>
                                        <input 
                                            type="checkbox" 
                                            checked={field.required}
                                            onChange={(e) => {
                                                const newFields = [...fields];
                                                newFields[index].required = e.target.checked;
                                                setFields(newFields);
                                            }}
                                            className="w-4 h-4 rounded-lg bg-white border-slate-200"
                                        />
                                    </div>
                                </div>

                                <div className="flex items-center gap-2">
                                    <button className="p-2 text-slate-400 hover:text-indigo-600 transition-colors">
                                        <Settings2 size={18} />
                                    </button>
                                    <button 
                                        onClick={() => removeField(field.id)}
                                        className="p-2 text-slate-400 hover:text-rose-600 transition-colors"
                                    >
                                        <Trash2 size={18} />
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default FormBuilder;

import React, { useState } from 'react';
import { 
  Plus, Search, ToggleLeft, ToggleRight, Calendar, Loader2, Trash2, Edit2, X, Save
} from 'lucide-react';
import { useTenants } from '../../hooks/useTenants';

const TenantList = () => {
  const { tenants, loading, saving, toggleStatus, updatePlan, addTenant } = useTenants();
  const [search, setSearch] = useState('');
  const [planFilter, setPlanFilter] = useState('All Plans');

  // Modal State
  const [editingTenant, setEditingTenant] = useState<any>(null);
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [editForm, setEditForm] = useState<any>({});
  const [addForm, setAddForm] = useState({
    name: '',
    email: '',
    phone: '',
    password: '',
    fullName: '',
    expiryDate: new Date(new Date().setFullYear(new Date().getFullYear() + 1)).toISOString().split('T')[0]
  });

  const handleToggleStatus = async (id: string, currentStatus: boolean) => {
    await toggleStatus(id, currentStatus);
  };

  const openEditModal = (tenant: any) => {
    setEditingTenant(tenant);
    setEditForm({
      plan: tenant.plan || 'basic',
      maxCars: tenant.limits?.maxCars || 50,
      maxLeads: tenant.limits?.maxLeads || 100,
      expiryDate: new Date(tenant.expiryDate).toISOString().split('T')[0]
    });
  };

  const closeEditModal = () => {
    setEditingTenant(null);
    setEditForm({});
  };

  const handleUpdateTenant = async () => {
    if (!editingTenant) return;
    const payload = {
      plan: editForm.plan.toUpperCase(),
      limits: {
        maxCars: Number(editForm.maxCars),
        maxLeads: Number(editForm.maxLeads)
      },
      expiryDate: new Date(editForm.expiryDate).toISOString()
    };
    await updatePlan(editingTenant._id || editingTenant.id, payload);
    closeEditModal();
  };

  const handleAddTenant = async (e: React.FormEvent) => {
    e.preventDefault();
    const payload = {
      tenantData: {
        name: addForm.name,
        expiryDate: new Date(addForm.expiryDate).toISOString()
      },
      adminData: {
        fullName: addForm.fullName,
        email: addForm.email,
        phone: addForm.phone,
        password: addForm.password
      }
    };
    const success = await addTenant(payload);
    if (success) {
      setIsAddModalOpen(false);
      setAddForm({
        name: '', email: '', phone: '', password: '', fullName: '',
        expiryDate: new Date(new Date().setFullYear(new Date().getFullYear() + 1)).toISOString().split('T')[0]
      });
    }
  };

  const filteredTenants = tenants.filter(t => {
    const matchesSearch = t.name.toLowerCase().includes(search.toLowerCase()) || 
      (t.slug && t.slug.toLowerCase().includes(search.toLowerCase()));
    const matchesPlan = planFilter === 'All Plans' || t.plan === planFilter.toUpperCase();
    return matchesSearch && matchesPlan;
  });

  return (
    <div className="space-y-8">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-black text-slate-900 tracking-tight">Showrooms</h1>
          <p className="text-slate-500 font-medium mt-1">Manage partner dealerships and their active subscriptions.</p>
        </div>
        <button 
          onClick={() => setIsAddModalOpen(true)}
          className="bg-indigo-600 text-white px-6 py-3 rounded-2xl font-bold flex items-center gap-2 hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100 transform hover:-translate-y-0.5 active:translate-y-0 text-sm"
        >
          <Plus size={18} />
          Add Showroom
        </button>
      </div>

      <div className="bg-white rounded-[2rem] border border-slate-100 shadow-xl shadow-slate-200/50 overflow-hidden">
        <div className="p-6 border-b border-slate-50 flex flex-col md:flex-row items-center gap-4 bg-slate-50/30">
          <div className="relative flex-1 w-full">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder="Search by name or slug..." 
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="w-full pl-12 pr-4 py-3 bg-white border border-slate-200 rounded-2xl focus:outline-none focus:ring-4 focus:ring-indigo-500/5 focus:border-indigo-500 transition-all text-sm font-medium"
            />
          </div>
          <select 
            value={planFilter}
            onChange={(e) => setPlanFilter(e.target.value)}
            className="bg-white border border-slate-200 rounded-2xl px-6 py-3 focus:outline-none focus:ring-4 focus:ring-indigo-500/5 focus:border-indigo-500 transition-all text-sm font-bold text-slate-600"
          >
            <option>All Plans</option>
            <option>Basic</option>
            <option>Pro</option>
            <option>Enterprise</option>
          </select>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-slate-50/50 border-b border-slate-50">
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Showroom</th>
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Plan Details</th>
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Status</th>
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Expiry</th>
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {loading ? (
                <tr>
                  <td colSpan={5} className="px-8 py-20 text-center">
                    <Loader2 className="w-8 h-8 animate-spin text-indigo-600 mx-auto" />
                    <p className="text-slate-500 font-medium mt-4">Syncing with global registry...</p>
                  </td>
                </tr>
              ) : filteredTenants.length === 0 ? (
                <tr>
                  <td colSpan={5} className="px-8 py-20 text-center text-slate-400 font-medium">
                    No showrooms matched your search.
                  </td>
                </tr>
              ) : filteredTenants.map((tenant) => (
                <tr key={tenant._id} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="px-8 py-5">
                    <div className="flex flex-col">
                      <span className="font-bold text-slate-900">{tenant.name}</span>
                      <span className="text-xs font-bold text-indigo-600 mt-0.5 tracking-tight group-hover:underline cursor-pointer">
                        automoto.ai/{tenant.slug || 'slug-pending'}
                      </span>
                    </div>
                  </td>
                  <td className="px-8 py-5">
                    <div className="flex items-center gap-2">
                        <span className={`px-3 py-1 rounded-lg text-[10px] font-black uppercase tracking-widest ${
                        tenant.plan === 'ENTERPRISE' ? 'bg-purple-100 text-purple-700' :
                        tenant.plan === 'PRO' ? 'bg-blue-100 text-blue-700' : 'bg-slate-100 text-slate-600'
                        }`}>
                        {tenant.plan}
                        </span>
                        <div className="h-1 w-1 bg-slate-300 rounded-full"></div>
                        <span className="text-xs font-bold text-slate-400">{tenant.limits?.maxCars || 50} Cars ΓÇó {tenant.limits?.maxLeads || 100} Leads</span>
                    </div>
                  </td>
                  <td className="px-8 py-5">
                    <button 
                        onClick={() => handleToggleStatus(tenant._id || tenant.id, tenant.isActive)}
                        className={`flex items-center gap-2 px-3 py-1.5 rounded-xl transition-all font-bold text-xs ${
                        tenant.isActive 
                            ? 'text-emerald-600 bg-emerald-50 hover:bg-emerald-100' 
                            : 'text-rose-600 bg-rose-50 hover:bg-rose-100'
                        }`}
                    >
                        {tenant.isActive ? <ToggleRight size={18} /> : <ToggleLeft size={18} />}
                        {tenant.isActive ? 'Active' : 'Halted'}
                    </button>
                  </td>
                  <td className="px-8 py-5">
                    <div className="flex items-center gap-2 text-slate-600">
                      <Calendar size={14} className="text-slate-400" />
                      <span className={`text-xs font-bold ${new Date(tenant.expiryDate) < new Date() ? 'text-rose-600' : ''}`}>
                          {new Date(tenant.expiryDate).toLocaleDateString()}
                      </span>
                    </div>
                  </td>
                  <td className="px-8 py-5 text-right">
                    <div className="flex items-center justify-end gap-2">
                        <button 
                            onClick={() => openEditModal(tenant)}
                            className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all"
                        >
                            <Edit2 size={16} />
                        </button>
                        <button className="p-2 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-all">
                            <Trash2 size={16} />
                        </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Edit Modal */}
      {editingTenant && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm">
          <div className="bg-white rounded-[2rem] w-full max-w-lg shadow-2xl overflow-hidden animate-in fade-in zoom-in-95 duration-200">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between">
              <h2 className="text-xl font-black text-slate-900">Manage Subscription</h2>
              <button onClick={closeEditModal} className="p-2 text-slate-400 hover:bg-slate-50 rounded-full transition-colors">
                <X size={20} />
              </button>
            </div>

            <div className="p-6 space-y-6">
                <div>
                    <span className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Showroom Name</span>
                    <p className="font-bold text-slate-900">{editingTenant.name}</p>
                </div>

                <div>
                    <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Plan Tier</label>
                    <select 
                        value={editForm.plan.toLowerCase()}
                        onChange={(e) => setEditForm((prev: any) => ({ ...prev, plan: e.target.value }))}
                        className="w-full px-4 py-3 bg-slate-50 border border-slate-100 rounded-xl font-bold text-slate-900 focus:outline-none focus:ring-2 focus:ring-indigo-500/20"
                    >
                        <option value="basic">Basic Plan</option>
                        <option value="pro">Pro Plan</option>
                        <option value="enterprise">Enterprise Plan</option>
                    </select>
                </div>

                <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Max Cars</label>
                        <input 
                            type="number" 
                            min="1"
                            value={editForm.maxCars}
                            onChange={(e) => setEditForm((prev: any) => ({ ...prev, maxCars: Number(e.target.value) }))}
                            className="w-full px-4 py-3 bg-slate-50 border border-slate-100 rounded-xl font-bold text-slate-900 focus:outline-none focus:ring-2 focus:ring-indigo-500/20"
                        />
                    </div>
                    <div>
                        <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Max Leads</label>
                        <input 
                            type="number" 
                            min="1"
                            value={editForm.maxLeads}
                            onChange={(e) => setEditForm((prev: any) => ({ ...prev, maxLeads: Number(e.target.value) }))}
                            className="w-full px-4 py-3 bg-slate-50 border border-slate-100 rounded-xl font-bold text-slate-900 focus:outline-none focus:ring-2 focus:ring-indigo-500/20"
                        />
                    </div>
                </div>

                <div>
                    <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Expiry Date</label>
                    <input 
                        type="date" 
                        value={editForm.expiryDate}
                        onChange={(e) => setEditForm((prev: any) => ({ ...prev, expiryDate: e.target.value }))}
                        className="w-full px-4 py-3 bg-slate-50 border border-slate-100 rounded-xl font-bold text-slate-900 focus:outline-none focus:ring-2 focus:ring-indigo-500/20"
                    />
                </div>
            </div>

            <div className="p-6 bg-slate-50 border-t border-slate-100 flex justify-end gap-3">
              <button 
                onClick={closeEditModal}
