                </div>

                <div>
                    <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Admin Full Name</label>
                    <input 
                        type="text" 
                        required
                        value={addForm.fullName}
                        onChange={(e) => setAddForm((prev: any) => ({ ...prev, fullName: e.target.value }))}
                        className="w-full px-4 py-3 bg-slate-50 border border-slate-100 rounded-xl font-bold text-slate-900 focus:outline-none focus:ring-2 focus:ring-indigo-500/20"
                        placeholder="e.g. John Doe"
                    />
                </div>

                <div>
                    <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Admin Email</label>
                    <input 
                        type="email" 
                        required
                        value={addForm.email}
                        onChange={(e) => setAddForm((prev: any) => ({ ...prev, email: e.target.value }))}
                        className="w-full px-4 py-3 bg-slate-50 border border-slate-100 rounded-xl font-bold text-slate-900 focus:outline-none focus:ring-2 focus:ring-indigo-500/20"
                        placeholder="admin@example.com"
                    />
                </div>

                <div>
                    <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Admin Phone</label>
                    <input 
                        type="text" 
                        required
                        value={addForm.phone}
                        onChange={(e) => setAddForm((prev: any) => ({ ...prev, phone: e.target.value }))}
                        className="w-full px-4 py-3 bg-slate-50 border border-slate-100 rounded-xl font-bold text-slate-900 focus:outline-none focus:ring-2 focus:ring-indigo-500/20"
                        placeholder="+91 9999999999"
                    />
                </div>

                <div>
                    <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Password</label>
                    <input 
                        type="password" 
                        required
                        minLength={8}
                        value={addForm.password}
                        onChange={(e) => setAddForm((prev: any) => ({ ...prev, password: e.target.value }))}
                        className="w-full px-4 py-3 bg-slate-50 border border-slate-100 rounded-xl font-bold text-slate-900 focus:outline-none focus:ring-2 focus:ring-indigo-500/20"
                        placeholder="Min 8 characters"
                    />
                </div>

                <div>
                    <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Initial Expiry</label>
                    <input 
                        type="date" 
                        required
                        value={addForm.expiryDate}
                        onChange={(e) => setAddForm((prev: any) => ({ ...prev, expiryDate: e.target.value }))}
                        className="w-full px-4 py-3 bg-slate-50 border border-slate-100 rounded-xl font-bold text-slate-900 focus:outline-none focus:ring-2 focus:ring-indigo-500/20"
                    />
                </div>
              </div>

              <div className="p-6 bg-slate-50 border-t border-slate-100 flex justify-end gap-3">
                <button 
                  type="button"
                  onClick={() => setIsAddModalOpen(false)}
                  className="px-6 py-2.5 rounded-xl font-bold text-slate-600 hover:bg-slate-200 transition-colors"
                >
                  Cancel
                </button>
                <button 
                  type="submit"
                  disabled={saving}
                  className="bg-indigo-600 text-white px-8 py-2.5 rounded-xl font-bold flex items-center gap-2 hover:bg-indigo-700 transition-all shadow-md shadow-indigo-100 disabled:opacity-50"
                >
                  {saving ? <Loader2 size={16} className="animate-spin" /> : <Plus size={16} />}
                  Create Showroom
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default TenantList;

import React, { useState, useEffect } from 'react';
import { MessageSquare, Shield, ExternalLink, Loader2, Save, Power } from 'lucide-react';
import api from '../../lib/api';
import toast from 'react-hot-toast';

const WhatsAppConfig = () => {
    const [tenants, setTenants] = useState([]);
    const [loading, setLoading] = useState(true);
    const [updating, setUpdating] = useState(false);

    useEffect(() => {
        const fetchTenants = async () => {
            try {
                const { data } = await api.get('/super/tenants');
                setTenants(data.data);
            } catch (error) {
                toast.error("Failed to fetch showrooms");
            } finally {
                setLoading(false);
            }
        };
        fetchTenants();
    }, []);

    const handleUpdateWA = async (id, config) => {
        setUpdating(true);
        try {
            await api.patch(`/super/tenants/${id}`, { whatsappConfig: config });
            toast.success("WhatsApp configuration updated");
            // Refresh local state
            setTenants(tenants.map(t => (t._id || t.id) === id ? { ...t, whatsappConfig: config } : t));
        } catch (error) {
            toast.error("Failed to update config");
        } finally {
            setUpdating(false);
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-64">
                <Loader2 className="w-8 h-8 animate-spin text-indigo-600" />
            </div>
        );
    }

    return (
        <div className="space-y-8 text-sans">
            <div>
                <h1 className="text-3xl font-black text-slate-900 tracking-tight">WhatsApp Configuration</h1>
                <p className="text-slate-500 font-medium mt-1">Manage global Evolution API instances for each showroom.</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {tenants.map((tenant) => (
                    <div key={tenant._id || tenant.id} className="bg-white rounded-[2rem] border border-slate-100 shadow-xl shadow-slate-200/50 p-6 flex flex-col justify-between group hover:border-indigo-200 transition-all duration-300">
                        <div>
                            <div className="flex items-center justify-between mb-4">
                                <div className="h-12 w-12 bg-indigo-50 rounded-2xl flex items-center justify-center text-indigo-600">
                                    <MessageSquare size={24} />
                                </div>
                                <span className={`px-3 py-1 rounded-lg text-[10px] font-black uppercase tracking-widest ${tenant.whatsappConfig?.isActive ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-100 text-slate-500'}`}>
                                    {tenant.whatsappConfig?.isActive ? 'Online' : 'Offline'}
                                </span>
                            </div>
                            <h3 className="text-xl font-bold text-slate-900">{tenant.name}</h3>
                            <p className="text-xs font-bold text-slate-400 mt-1 uppercase tracking-wider">{tenant.slug}</p>

                            <div className="mt-6 space-y-4">
                                <div>
                                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2">Instance ID</label>
                                    <input 
                                        type="text" 
                                        defaultValue={tenant.whatsappConfig?.instanceId || ''}
                                        onBlur={(e) => handleUpdateWA(tenant._id || tenant.id, { ...tenant.whatsappConfig, instanceId: e.target.value })}
                                        className="w-full px-4 py-2 bg-slate-50 border border-slate-100 rounded-xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 transition-all text-sm font-medium"
                                        placeholder="Enter Instance ID"
