import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { useDropzone } from 'react-dropzone';
import {
    Bike,
    Car,
    Upload,
    X,
    MapPin,
    Info,
    IndianRupee,
    Save,
    ArrowLeft,
    Loader2
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { cn } from '../../lib/utils';
import { useVehicles } from '../../hooks/useVehicles';
import { ROUTES } from '../../constants/routes';

interface InputGroupProps {
    label: string;
    children: React.ReactNode;
    required?: boolean;
}

const InputGroup = ({ label, children, required }: InputGroupProps) => (
    <div className="space-y-1">
        <label className="block text-sm font-medium text-gray-700">
            {label} {required && <span className="text-red-500">*</span>}
        </label>
        {children}
    </div>
);

interface FileWithPreview extends File {
    preview: string;
}

export default function AddVehicle() {
    const navigate = useNavigate();
    const { saving, createVehicle } = useVehicles();
    const [vehicleType, setVehicleType] = useState('bike');
    const [files, setFiles] = useState<FileWithPreview[]>([]);
    const [form, setForm] = useState({
        name: '',
        year: new Date().getFullYear(),
        registrationNumber: '',
        km_driven: 0,
        fuel: 'Petrol',
        transmission: 'Manual',
        ownership: '1st Owner',
        price: 0,
        status: 'Available',
        isNegotiable: false,
        city: 'Bangalore',
        area: 'Koramangala',
    });

    const onDrop = (acceptedFiles: File[]) => {
        setFiles(prev => [...prev, ...acceptedFiles.map(file => Object.assign(file, {
            preview: URL.createObjectURL(file)
        }) as FileWithPreview)]);
    };

    const { getRootProps, getInputProps, isDragActive } = useDropzone({ onDrop, accept: { 'image/*': [] } });

    const removeFile = (name: string) => {
        setFiles(files.filter(f => f.name !== name));
    };

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value, type } = e.target;
        setForm(prev => ({
            ...prev,
            [name]: type === 'checkbox' ? (e.target as HTMLInputElement).checked
                : ['year', 'km_driven', 'price'].includes(name) ? Number(value)
                : value
        }));
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        const success = await createVehicle({
            name: form.name,
            year: form.year,
            km_driven: form.km_driven,
            fuel: form.fuel,
            transmission: form.transmission,
            ownership: form.ownership,
            price: form.price,
            status: form.status,
            type: vehicleType,
            city: form.city,
            area: form.area,
            isNegotiable: form.isNegotiable,
        });
        if (success) navigate(ROUTES.VEHICLES.BASE);
    };

    return (
        <div className="max-w-4xl mx-auto space-y-6 font-sans">
            <div className="flex items-center gap-4">
                <button onClick={() => navigate(-1)} className="p-2 hover:bg-gray-100 rounded-full transition-colors">
                    <ArrowLeft className="w-5 h-5 text-gray-500" />
                </button>
                <div>
                    <h1 className="text-2xl font-bold text-gray-900">Add New Vehicle</h1>
                    <p className="text-sm text-gray-500">Fill in the details to list your vehicle</p>
                </div>
            </div>

            <form onSubmit={handleSubmit} className="space-y-6">

                {/* 1. Basic Details */}
                <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 space-y-6">
                    <h2 className="text-lg font-semibold flex items-center gap-2">
                        <Info className="w-5 h-5 text-blue-500" />
                        Basic Details
                    </h2>

                    <div className="flex gap-4">
                        <button
                            type="button"
                            onClick={() => setVehicleType('bike')}
                            className={cn(
                                "flex-1 py-3 px-4 rounded-lg border-2 flex items-center justify-center gap-2 transition-all font-medium",
                                vehicleType === 'bike'
                                    ? "border-blue-600 bg-blue-50 text-blue-700"
                                    : "border-gray-200 hover:border-gray-300 text-gray-600"
                            )}
                        >
                            <Bike className="w-5 h-5" /> Bike
                        </button>
                        <button
                            type="button"
                            onClick={() => setVehicleType('car')}
                            className={cn(
                                "flex-1 py-3 px-4 rounded-lg border-2 flex items-center justify-center gap-2 transition-all font-medium",
                                vehicleType === 'car'
                                    ? "border-blue-600 bg-blue-50 text-blue-700"
                                    : "border-gray-200 hover:border-gray-300 text-gray-600"
                            )}
                        >
                            <Car className="w-5 h-5" /> Car
                        </button>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <InputGroup label="Vehicle Name" required>
                            <input name="name" type="text" placeholder="e.g. Yamaha R15 V3" value={form.name} onChange={handleChange} required
                                className="w-full p-2.5 border border-gray-300 rounded-lg focus:ring-blue-500 focus:border-blue-500 bg-white text-gray-900" />
                        </InputGroup>
                        <InputGroup label="Model Year" required>
                            <input name="year" type="number" placeholder="2021" value={form.year} onChange={handleChange} required
                                className="w-full p-2.5 border border-gray-300 rounded-lg focus:ring-blue-500 focus:border-blue-500 bg-white text-gray-900" />
                        </InputGroup>
                        <InputGroup label="Registration Number" required>
                            <input name="registrationNumber" type="text" placeholder="KA 05 AB 1234" onChange={handleChange} required
                                className="w-full p-2.5 border border-gray-300 rounded-lg focus:ring-blue-500 focus:border-blue-500 uppercase bg-white text-gray-900" />
                        </InputGroup>
                        <InputGroup label="Kilometers Driven" required>
                            <input name="km_driven" type="number" placeholder="15000" value={form.km_driven} onChange={handleChange} required
                                className="w-full p-2.5 border border-gray-300 rounded-lg focus:ring-blue-500 focus:border-blue-500 bg-white text-gray-900" />
                        </InputGroup>
                        <InputGroup label="Fuel Type" required>
                            <select name="fuel" value={form.fuel} onChange={handleChange}
                                className="w-full p-2.5 border border-gray-300 rounded-lg focus:ring-blue-500 focus:border-blue-500 bg-white text-gray-900">
                                <option>Petrol</option>
                                <option>Diesel</option>
                                <option>Electric</option>
                                <option>CNG</option>
                            </select>
                        </InputGroup>
                        <InputGroup label="Transmission" required>
                            <select name="transmission" value={form.transmission} onChange={handleChange}
                                className="w-full p-2.5 border border-gray-300 rounded-lg focus:ring-blue-500 focus:border-blue-500 bg-white text-gray-900">
                                <option>Manual</option>
                                <option>Automatic</option>
                            </select>
                        </InputGroup>
                        <InputGroup label="Ownership" required>
                            <select name="ownership" value={form.ownership} onChange={handleChange}
                                className="w-full p-2.5 border border-gray-300 rounded-lg focus:ring-blue-500 focus:border-blue-500 bg-white text-gray-900">
                                <option>1st Owner</option>
                                <option>2nd Owner</option>
                                <option>3rd Owner</option>
                            </select>
                        </InputGroup>
                    </div>
                </div>

                {/* 2. Media */}
                <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 space-y-6">
                    <h2 className="text-lg font-semibold flex items-center gap-2">
                        <Upload className="w-5 h-5 text-blue-500" />
                        Vehicle Photos
                    </h2>

                    <div {...getRootProps()} className={cn(
                        "border-2 border-dashed rounded-xl p-4 sm:p-8 text-center cursor-pointer transition-colors",
                        isDragActive ? "border-blue-500 bg-blue-50" : "border-gray-300 hover:border-gray-400"
                    )}>
                        <input {...getInputProps()} />
                        <div className="mx-auto w-10 h-10 sm:w-12 sm:h-12 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center mb-3">
                            <Upload className="w-5 h-5 sm:w-6 sm:h-6" />
                        </div>
                        <p className="text-sm text-gray-600">
                            <span className="font-medium text-blue-600">Click to upload</span> <span className="hidden sm:inline">or drag and drop</span>
                        </p>
                        <p className="text-xs text-gray-400 mt-1">SVG, PNG, JPG or GIF (max. 5MB)</p>
                    </div>

                    {files.length > 0 && (
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                            {files.map((file) => (
                                <div key={file.name} className="relative group rounded-lg overflow-hidden border border-gray-200 aspect-square">
                                    <img
                                        src={file.preview}
                                        alt={file.name}
                                        className="w-full h-full object-cover"
                                        onLoad={() => { URL.revokeObjectURL(file.preview) }}
                                    />
                                    <button
                                        type="button"
