                {/* 3. Pricing & Status */}
                <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 space-y-6">
                    <h2 className="text-lg font-semibold flex items-center gap-2">
                        <IndianRupee className="w-5 h-5 text-blue-500" />
                        Pricing & Status
                    </h2>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <InputGroup label="Expected Price" required>
                            <div className="relative">
                                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                                    <span className="text-gray-500">Γé╣</span>
                                </div>
                                <input name="price" type="number" placeholder="0.00" value={form.price} onChange={handleChange}
                                    className="w-full pl-8 p-2.5 border border-gray-300 rounded-lg focus:ring-blue-500 focus:border-blue-500 bg-white text-gray-900" />
                            </div>
                        </InputGroup>
                        <InputGroup label="Status" required>
                            <select name="status" value={form.status} onChange={handleChange}
                                className="w-full p-2.5 border border-gray-300 rounded-lg focus:ring-blue-500 focus:border-blue-500 bg-white text-gray-900">
                                <option>Available</option>
                                <option>Reserved</option>
                                <option>Sold</option>
                            </select>
                        </InputGroup>
                        <div className="flex items-center gap-2 pt-2 sm:pt-6">
                            <input name="isNegotiable" type="checkbox" id="negotiable" checked={form.isNegotiable} onChange={handleChange}
                                className="w-4 h-4 text-blue-600 rounded border-gray-300 focus:ring-blue-500 bg-white" />
