                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <InputGroup label="City" required>
                            <input name="city" type="text" value={form.city} onChange={handleChange}
                                className="w-full p-2.5 border border-gray-300 rounded-lg focus:ring-blue-500 focus:border-blue-500 bg-white text-gray-900" />
                        </InputGroup>
                        <InputGroup label="Area" required>
                            <input name="area" type="text" value={form.area} onChange={handleChange}
                                className="w-full p-2.5 border border-gray-300 rounded-lg focus:ring-blue-500 focus:border-blue-500 bg-white text-gray-900" />
